<template>
 <div class="continuation" v-loading="busy">
  <div v-if="canApply" class="continue-entry"><div><strong>继续原商品换出</strong><p class="muted">复用已完成的退回验收，审核后为尚未实际发出的数量建立新一轮换出需求。</p></div><el-button v-hasPermi="['order:exchange:execute']" size="small" type="primary" plain @click="openApply">继续换出</el-button></div>
  <section v-for="r in pending" :key="r.id" class="pending-round"><div class="pending-heading"><strong>第 {{ r.round_no }} 轮继续换出 · 待审核</strong><el-button v-hasPermi="['order:exchange:review']" type="primary" size="small" @click="openReview(r)">审核继续换出</el-button></div><p>{{ r.target_sku }} · 本轮 {{ r.quantity }} 件</p><p class="muted">申请依据：{{ r.reason }} · 凭证：{{ r.evidence }}</p><p class="muted">本轮收货：{{ address(r.recipient_json) }}</p><el-alert title="本次申请尚未重新预占，也未下发仓库。审核时须再次核对未退款及无冲突售后。" type="info" :closable="false" /></section>
  <el-dialog title="申请继续换出" :visible.sync="applyVisible" width="min(800px,96vw)" append-to-body :close-on-click-modal="false"><el-alert title="沿用本换货单及退回验收，新一轮独立预占和生成发货单；旧单据及截单记录保留。" type="info" :closable="false" /><div class="continue-summary"><span>本次批准 {{ exchange.requested_quantity }} 件</span><span>已退回入账 {{ preview.returned && preview.returned.posted_quantity }} 件</span><span>累计实际换出 {{ preview.shipped_quantity }} 件</span><strong>本轮继续换出 {{ preview.quantity }} 件</strong></div><el-form label-width="115px"><el-form-item label="目标商品 / SKU">{{ exchange.target_goods && (exchange.target_goods.goodsName || exchange.target_goods.goods_name) || exchange.target_sku }}<div class="muted">{{ exchange.target_sku }} · 本期仅继续原商品和全部剩余数量</div></el-form-item><el-form-item label="本轮收件人"><el-input v-model.trim="form.replacement_recipient.name" maxlength="100" /></el-form-item><el-form-item label="联系电话"><el-input v-model.trim="form.replacement_recipient.mobile" maxlength="100" /></el-form-item><el-form-item label="省 / 市 / 区"><div class="recipient-region"><el-input v-model.trim="form.replacement_recipient.province" placeholder="省" maxlength="100" /><el-input v-model.trim="form.replacement_recipient.city" placeholder="市" maxlength="100" /><el-input v-model.trim="form.replacement_recipient.area" placeholder="区 / 县" maxlength="100" /></div></el-form-item><el-form-item label="详细地址"><el-input v-model.trim="form.replacement_recipient.detailAddress" maxlength="500" /></el-form-item><el-form-item label="协商依据"><el-input v-model.trim="form.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item><el-form-item label="核对凭证"><el-input v-model.trim="form.evidence" type="textarea" maxlength="500" show-word-limit placeholder="买家协商、平台或外部售后核对的工单引用" /></el-form-item><el-form-item label="自动审核授权"><el-checkbox v-model="form.automation_authorized">允许按本店规则自动审核本轮申请</el-checkbox><el-input v-if="form.automation_authorized" v-model.trim="form.authorization_reference" maxlength="200" placeholder="商家授权 / 协商工单编号" /></el-form-item><el-form-item label="确认事项"><el-checkbox v-model="form.buyer_confirmed">买家已同意继续换出该商品和数量</el-checkbox><br><el-checkbox v-model="form.refund_confirmed">已核对未退款、无退款处理中及其他冲突售后</el-checkbox><br><el-checkbox v-model="form.recipient_confirmed">已核对本轮换出收货信息</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="applyVisible=false">返回</el-button><el-button type="primary" :loading="busy" @click="submit">提交继续换出申请</el-button></span></el-dialog>
  <el-dialog title="审核继续换出" :visible.sync="reviewVisible" width="min(720px,96vw)" append-to-body :close-on-click-modal="false"><el-descriptions border :column="1" size="small"><el-descriptions-item label="本轮商品">{{ selected.target_sku }} · {{ selected.quantity }} 件</el-descriptions-item><el-descriptions-item label="本轮收货">{{ address(selected.recipient_json) }}</el-descriptions-item><el-descriptions-item label="协商依据 / 凭证">{{ selected.reason }}<div class="muted">{{ selected.evidence }}</div></el-descriptions-item></el-descriptions><el-form label-width="100px" class="review-form"><el-form-item label="审核结论"><el-radio-group v-model="review.decision"><el-radio label="APPROVE">通过，重新预占</el-radio><el-radio label="REJECT">拒绝本次申请</el-radio></el-radio-group></el-form-item><el-form-item label="审核依据"><el-input v-model.trim="review.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item><el-form-item v-if="review.decision === 'APPROVE'" label="售后核对"><el-checkbox v-model="review.refund_confirmed">再次核对未退款且无冲突售后</el-checkbox></el-form-item></el-form><el-alert title="通过后先重新预占，库存不足保留本轮数量和待办；分仓、匹配快递及下发仍从换出发货处理。" type="info" :closable="false" /><span slot="footer"><el-button @click="reviewVisible=false">返回</el-button><el-button type="primary" :loading="busy" @click="reviewSubmit">保存审核结果</el-button></span></el-dialog>
 </div>
</template>
<script>
import { exchangeAction, exchangeContinuationPreview } from '@/api/order/exchange'
export default {
 props:{exchange:{type:Object,required:true}},
 data(){return {busy:false,applyVisible:false,reviewVisible:false,preview:{},form:{replacement_recipient:{}},selected:{},review:{decision:'APPROVE',reason:'',refund_confirmed:false}}},
 computed:{pending(){return (this.exchange.fulfillment_rounds||[]).filter(r=>r.state==='REVIEW')},canApply(){return !this.exchange.linked_exchange_id&&!this.pending.length&&this.exchange.return_qc==='PASSED'&&(this.exchange.state==='CLOSED'||this.exchange.control_state==='HOLD')}},
 methods:{object(raw){if(raw&&typeof raw==='object')return raw;try{return JSON.parse(raw||'{}')}catch(_){return {}}},address(raw){const r=this.object(raw);return [r.name,r.mobile,r.province,r.city,r.area,r.town,r.detailAddress].filter(Boolean).join(' ')||'收货信息待核对'},async openApply(){if(this.busy)return;this.busy=true;try{this.preview=(await exchangeContinuationPreview(this.exchange.id)).data;this.form={quantity:this.preview.quantity,replacement_recipient:{...this.preview.recipient},reason:'',evidence:'',automation_authorized:false,authorization_reference:'',buyer_confirmed:false,refund_confirmed:false,recipient_confirmed:false};this.applyVisible=true}finally{this.busy=false}},async submit(){if(!this.form.reason||!this.form.evidence)return this.$message.warning('请填写协商依据和核对凭证');if(!this.form.buyer_confirmed||!this.form.refund_confirmed||!this.form.recipient_confirmed)return this.$message.warning('请完成买家意愿、售后状态和地址核对');return this.command('continuations',{...this.form,control_version:this.preview.control_version})},openReview(r){this.selected=r;this.review={decision:'APPROVE',reason:'',refund_confirmed:false};this.reviewVisible=true},async reviewSubmit(){if(!this.review.reason)return this.$message.warning('请填写审核依据');if(this.review.decision==='APPROVE'&&!this.review.refund_confirmed)return this.$message.warning('请再次核对未退款及无冲突售后');return this.command('continuations/'+this.selected.round_no+'/review',{...this.review,control_version:this.exchange.control_version})},async command(action,data){if(this.busy)return;this.busy=true;try{await exchangeAction(this.exchange.id,action,data);this.applyVisible=false;this.reviewVisible=false;this.$emit('changed');this.$message.success(action==='continuations'?'已登记，等待审核；尚未重新预占':'审核结果已保存，请查看本轮换出进度')}finally{this.busy=false}}}
}
</script>
<style scoped>.continue-entry,.pending-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.continue-entry{margin:16px 0;padding:14px;background:#f2f7ff;border-radius:6px}.muted{font-size:12px;line-height:1.8;color:#7f8da1;margin:6px 0}.pending-round{padding:16px;border:1px solid #e6d5ad;background:#fffaf0;border-radius:6px;margin:14px 0}.continue-summary{display:flex;flex-wrap:wrap;gap:14px;background:#f3f7fc;padding:16px;margin:18px 0}.recipient-region{display:flex;gap:8px}.review-form{margin-top:20px}</style>
